options.elementValueChanged:
if (context.element.id === 'part_number') {
  const series = context.panel.data?.series;
  if (series && series.length > 1) {
    const frame = series[1];
    const partF = frame.fields.find(f => f.name === 'part_number');
    const costF = frame.fields.find(f => f.name === 'cost_per_unit');
    const descF = frame.fields.find(f => f.name === 'description');
    if (partF && costF) {
      for (let i = 0; i < partF.values.length; i++) {
        if (String(partF.values[i]) === String(context.element.value)) {
          const updated = context.panel.elements.map(el => ({
            ...el,
            helpers: el.helpers || {},
            ...(el.id === 'cost_per_unit' ? { value: costF.values[i] } : {}),
            ...(el.id === 'description' ? { value: descF.values[i] || '' } : {})
          }));
          context.panel.onChangeElements(updated);
          break;
        }
      }
    }
  }
}

if (context.element.id === 'line_name') {
  const series = context.panel.data?.series;
  if (series && series.length > 1) {
    const frame = series[1];
    const lineF = frame.fields.find(f => f.name === 'line_name');
    const costF = frame.fields.find(f => f.name === 'cost_per_hour');
    if (lineF && costF) {
      for (let i = 0; i < lineF.values.length; i++) {
        if (String(lineF.values[i]) === String(context.element.value)) {
          const updated = context.panel.elements.map(el => ({
            ...el,
            helpers: el.helpers || {},
            ...(el.id === 'cost_per_hour' ? { value: costF.values[i] } : {})
          }));
          context.panel.onChangeElements(updated);
          break;
        }
      }
    }
  }
}
